1	#!/usr/bin/env python3
2	"""ClientBook HTTP service."""
3	import argparse
4	import datetime
5	import json
6	import re
7	import signal
8	import sqlite3
9	from http.server import BaseHTTPRequestHandler, HTTPServer
10	from pathlib import Path
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "ClientBook"
14	RESOURCE = "clients"
15	OPTIONAL_FIELDS = ("source", "region", "industry", "important_date")
16	ALL_COLUMNS = ("name",) + OPTIONAL_FIELDS
17	MAX_BODY = 10 * 1024 * 1024
18	DATE_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
19	
20	PAGE = '''<!doctype html>
21	<html lang="zh-CN">
22	<head>
23	<meta charset="utf-8">
24	<meta name="viewport" content="width=device-width,initial-scale=1">
25	<title>ClientBook · 客户联系人与商机记录</title>
26	<style>
27	body{font-family:system-ui,sans-serif;max-width:60rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1c2733}
28	a{color:#175b9c}
29	h1{margin-bottom:.2rem}
30	.subtitle{color:#5b6b7b;margin-top:0}
31	.card{border:1px solid #d8dee6;border-radius:8px;padding:1rem 1.25rem;margin:1.5rem 0}
32	.card h2{margin-top:0;font-size:1.15rem}
33	.filename{margin-left:.5rem;color:#5b6b7b}
34	button{font-size:1rem;padding:.45rem 1.4rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
35	button:disabled{background:#9db6cc;border-color:#9db6cc;cursor:default}
36	.hint{color:#5b6b7b;font-size:.9rem;margin:.35rem 0 0}
37	#report{display:none;margin-top:1rem}
38	.banner{padding:.6rem 1rem;border-radius:6px;margin-bottom:.75rem}
39	.banner.ok{background:#e9f7ec;border:1px solid #bfe3c8}
40	.banner.bad{background:#fdeeee;border:1px solid #f3c4c4}
41	.banner.warn{background:#fdf6e6;border:1px solid #ecd9a8}
42	.banner.busy{background:#eef4fb;border:1px solid #c3d5e8}
43	.failures{border:1px solid #ecd7d7;background:#fdf6f6;border-radius:6px;padding:.5rem 1rem;max-height:16rem;overflow:auto}
44	.failures b{color:#a02b2b}
45	.failures ul{margin:.4rem 0}
46	table{border-collapse:collapse;width:100%}
47	#clients-table{display:none}
48	#clients-table.on{display:table}
49	#clients-empty{display:none}
50	#clients-empty.on{display:block}
51	#clients-load-error{display:none}
52	#clients-load-error.on{display:block;color:#a06a16}
53	th,td{text-align:left;padding:.45rem .6rem;border-bottom:1px solid #e3e8ee;vertical-align:top}
54	th{font-size:.85rem;color:#5b6b7b;font-weight:600}
55	.muted{color:#9aa7b4}
56	#clients-body tr.selected{background:#f1f6fb}
57	.sel-panel{background:#f5f8fb;border:1px solid #d8dee6;border-radius:6px;padding:.6rem .8rem;margin:.8rem 0}
58	.sel-list{margin-top:.35rem}
59	.sel-chip{display:inline-block;background:#fff;border:1px solid #cdd7e2;border-radius:999px;padding:.1rem .35rem .1rem .6rem;margin:.2rem .35rem .2rem 0;font-size:.9rem;white-space:nowrap}
60	.sel-chip button{border:none;background:none;color:#5b6b7b;font-size:1.05rem;line-height:1;padding:0 .25rem;cursor:pointer}
61	.sel-chip button:hover{color:#a02b2b}
62	.bf{border:1px solid #d8dee6;border-radius:6px;padding:.55rem .8rem;margin:.6rem 0}
63	.bf-head{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;margin-bottom:.35rem}
64	.bf-head b{min-width:4.5rem}
65	.bf-head label{font-weight:400;white-space:nowrap}
66	.bf textarea{width:100%;box-sizing:border-box;font:inherit;resize:vertical;padding:.3rem .45rem}
67	.bf input[type=text]{font:inherit;padding:.3rem .45rem}
68	.bf textarea:disabled,.bf input:disabled{background:#f2f4f7;color:#8a97a5}
69	.bf .val-hint{margin:.25rem 0 0;font-size:.85rem;color:#5b6b7b}
70	#batch-report{margin-top:.75rem}
71	.footer{color:#5b6b7b;font-size:.9rem;margin-top:2rem}
72	</style>
73	</head>
74	<body>
75	<main>
76	<h1>ClientBook</h1>
77	<p class="subtitle">客户联系人与商机记录</p>
78	
79	<section class="card">
80	<h2>从 CSV 导入客户</h2>
81	<form id="import-form">
82	  <!-- 不使用原生 required 拦截：未选文件时由提交处理统一在页内提示先选择 CSV，
83	       与批量修改表单的自定义校验提示口径一致，避免原生气泡拦截后页内无提示。 -->
84	  <input type="file" id="file-input" accept=".csv,text/csv,text/plain">
85	  <span class="filename" id="filename"></span>
86	  <div style="margin-top:.75rem"><button type="submit" id="submit-btn">导入</button></div>
87	</form>
88	<p class="hint">表头须包含 name（必需），可选 source、region、industry、important_date，顺序不限；重要日期须为 YYYY-MM-DD 真实日期。支持带引号字段与字段内换行（UTF-8，可带 BOM）。</p>
89	<div id="report"></div>
90	</section>
91	
92	<h2>客户列表</h2>
93	<p id="clients-empty" class="muted">还没有客户记录。</p>
94	<p id="clients-load-error" class="muted"></p>
95	<table id="clients-table">
96	  <thead><tr><th style="width:2.2rem"><input type="checkbox" id="check-all" title="全选/取消全选当前列表"></th><th>编号</th><th>客户名称</th><th>来源</th><th>地区</th><th>行业</th><th>重要日期</th></tr></thead>
97	  <tbody id="clients-body"></tbody>
98	</table>
99	
100	<section class="card" id="batch-card">
101	<h2>批量修改选中客户</h2>
102	<div class="sel-panel">
103	  已选择 <b id="sel-count">0</b> 名客户：
104	  <div class="sel-list" id="sel-list"><span class="muted" id="sel-none">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span></div>
105	</div>
106	<form id="batch-form">
107	  <div id="batch-fields"></div>
108	  <p class="hint">每个字段可分别选择「保持原值」「设为填写的值」或「清空」；初次进入编辑时全部保持原值，留空不会清空资料。来源、地区和行业保留内部空白与换行，仅含空白的填写值按清空处理；重要日期须为 YYYY-MM-DD 真实日历日期。客户名称和编号不参与编辑，也不会新建客户。</p>
109	  <div style="margin-top:.6rem">
110	    <button type="submit" id="batch-submit" disabled>保存修改</button>
111	  </div>
112	</form>
113	<div id="batch-report"></div>
114	</section>
115	
116	<p class="footer"><a href="/api/clients">查看客户列表接口</a> · <a href="/health">服务状态</a></p>
117	</main>
118	<script>
119	const ESC = {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"};
120	const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ESC[c]);
121	const blank = v => (v === null || v === undefined || v === "") ? '<span class="muted">—</span>' : esc(v);
122	
123	const BATCH_FIELDS = [
124	  {key: "source", label: "来源"},
125	  {key: "region", label: "地区"},
126	  {key: "industry", label: "行业"},
127	  {key: "important_date", label: "重要日期", date: true},
128	];
129	
130	let clients = [];
131	const selected = new Set();
132	// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
133	// 勾选变化与表单重复提交都不能解除或新增请求。
134	let batchSaving = false;
135	// 一次 CSV 导入从提交文件开始，到回复读取、结果展示以及该结果需要的客户列表
136	// 刷新全部结束期间为 true：期间只能有最初发出的那一次导入请求；重复点击、
137	// 回车等再次触发表单提交都直接忽略，不解除等待、不新增请求、不更换提示。
138	let importing = false;
139	
140	function syncSubmitState() {
141	  const btn = document.getElementById("batch-submit");
142	  btn.disabled = batchSaving || selected.size === 0;
143	  btn.textContent = batchSaving ? "正在保存…" : "保存修改";
144	}
145	
146	function syncImportState() {
147	  const btn = document.getElementById("submit-btn");
148	  btn.disabled = importing;
149	  btn.textContent = importing ? "正在导入…" : "导入";
150	}
151	
152	async function loadClients() {
153	  // 只在明确读到有效客户列表（真正的空列表也算）时才更新页面；
154	  // 连接错误、非成功状态、响应无法解析或未包含 clients 数组都视为读取失败：
155	  // 保留此前已显示的客户编号、名称与各字段内容，不清空表格、不显示空列表提示。
156	  const note = document.getElementById("clients-load-error");
157	  let list;
158	  try {
159	    const res = await fetch("/api/clients");
160	    if (!res.ok) throw new Error("服务返回非成功状态（HTTP " + res.status + "）");
161	    const data = await res.json();
162	    if (!data || !Array.isArray(data.clients)) {
163	      throw new Error("响应未包含有效的客户列表");
164	    }
165	    list = data.clients;
166	  } catch (err) {
167	    let message = err.message;
168	    if (err instanceof SyntaxError) message = "响应无法解析为有效数据";
169	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
170	    note.textContent = "客户列表读取失败：" + message +
171	      "，当前显示的资料可能不是最新内容；保存结果不受影响，稍后刷新页面即可重新读取。";
172	    note.classList.add("on");
173	    // 读取失败期间不能让表格或“还没有客户记录”冒充真实的空列表；
174	    // 此前已渲染的行保留不动，之后真正读到空列表时再由 renderClients 恢复空状态提示。
175	    document.getElementById("clients-empty").classList.remove("on");
176	    throw new Error(message);
177	  }
178	  note.classList.remove("on");
179	  note.textContent = "";
180	  clients = list;
181	  const known = new Set(clients.map(r => r.id));
182	  for (const id of [...selected]) {
183	    if (!known.has(id)) selected.delete(id);
184	  }
185	  renderClients();
186	  renderSelection();
187	}
188	
189	function renderClients() {
190	  const tbl = document.getElementById("clients-table");
191	  const empty = document.getElementById("clients-empty");
192	  const body = document.getElementById("clients-body");
193	  if (clients.length) {
194	    tbl.classList.add("on");
195	    empty.classList.remove("on");
196	    body.innerHTML = clients.map(r =>
197	      '<tr data-id="' + esc(r.id) + '"' + (selected.has(r.id) ? ' class="selected"' : "") + ">" +
198	      '<td><input type="checkbox" class="row-check" value="' + esc(r.id) + '"' +
199	      (selected.has(r.id) ? " checked" : "") + " aria-label='选择客户 " + esc(r.id) + "'></td>" +
200	      "<td>" + esc(r.id) + "</td><td>" + esc(r.name) + "</td><td>" + blank(r.source) +
201	      "</td><td>" + blank(r.region) + "</td><td>" + blank(r.industry) +
202	      "</td><td>" + blank(r.important_date) + "</td></tr>").join("");
203	  } else {
204	    tbl.classList.remove("on");
205	    empty.classList.add("on");
206	    body.innerHTML = "";
207	  }
208	  syncCheckAll();
209	}
210	
211	function syncCheckAll() {
212	  const box = document.getElementById("check-all");
213	  box.checked = clients.length > 0 && selected.size === clients.length;
214	  box.indeterminate = selected.size > 0 && selected.size < clients.length;
215	}
216	
217	function renderSelection() {
218	  document.getElementById("sel-count").textContent = String(selected.size);
219	  const list = document.getElementById("sel-list");
220	  if (!selected.size) {
221	    list.innerHTML = '<span class="muted">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span>';
222	  } else {
223	    const byId = new Map(clients.map(r => [r.id, r]));
224	    list.innerHTML = [...selected].sort((a, b) => a - b).map(id => {
225	      const r = byId.get(id);
226	      return '<span class="sel-chip">#' + esc(id) + " " + esc(r ? r.name : "") +
227	        ' <button type="button" data-remove="' + esc(id) + '" title="取消勾选该客户">×</button></span>';
228	    }).join("");
229	  }
230	  syncSubmitState();
231	  document.querySelectorAll("#clients-body tr").forEach(tr => {
232	    tr.classList.toggle("selected", selected.has(Number(tr.dataset.id)));
233	  });
234	  syncCheckAll();
235	}
236	
237	function buildBatchFields() {
238	  const wrap = document.getElementById("batch-fields");
239	  wrap.innerHTML = BATCH_FIELDS.map(f =>
240	    '<div class="bf" data-field="' + f.key + '">' +
241	      '<div class="bf-head"><b>' + f.label + "</b>" +
242	        '<label><input type="radio" name="' + f.key + '-op" value="keep" checked> 保持原值</label>' +
243	        '<label><input type="radio" name="' + f.key + '-op" value="set"> 设为填写的值</label>' +
244	        '<label><input type="radio" name="' + f.key + '-op" value="clear"> 清空</label>' +
245	      "</div>" +
246	      (f.date
247	        ? '<input type="text" class="bf-value" disabled placeholder="YYYY-MM-DD" autocomplete="off">'
248	        : '<textarea class="bf-value" rows="2" disabled></textarea>') +
249	      '<p class="val-hint">' + (f.date
250	        ? "非空时须为 YYYY-MM-DD 真实日历日期；仅含空白的填写值按清空处理。"
251	        : "去除前后空白后保存，内部空白与换行保留；仅含空白的填写值按清空处理。") +
252	      "</p></div>").join("");
253	  wrap.querySelectorAll(".bf").forEach(card => {
254	    const input = card.querySelector(".bf-value");
255	    card.querySelectorAll('input[type=radio]').forEach(radio => radio.addEventListener("change", () => {
256	      const op = card.querySelector('input[type=radio]:checked').value;
257	      input.disabled = op !== "set";
258	      if (op === "set") input.focus();
259	    }));
260	  });
261	}
262	
263	function collectBatchPayload() {
264	  const updates = {};
265	  for (const card of document.querySelectorAll("#batch-fields .bf")) {
266	    const key = card.dataset.field;
267	    const op = card.querySelector('input[type=radio]:checked').value;
268	    if (op === "keep") {
269	      updates[key] = {op: "keep"};
270	    } else if (op === "clear") {
271	      updates[key] = {op: "clear"};
272	    } else {
273	      updates[key] = {op: "set", value: card.querySelector(".bf-value").value};
274	    }
275	  }
276	  return {ids: [...selected].sort((a, b) => a - b), updates};
277	}
278	
279	function resetBatchForm() {
280	  document.querySelectorAll("#batch-fields .bf").forEach(card => {
281	    card.querySelector('input[value=keep]').checked = true;
282	    const input = card.querySelector(".bf-value");
283	    input.value = "";
284	    input.disabled = true;
285	  });
286	}
287	
288	function showBatchReport(html) {
289	  document.getElementById("batch-report").innerHTML = html;
290	}
291	
292	// CSV 导入与批量修改共用的服务回复读取：先取回复原文，再尝试解析为 JSON。
293	// parsed 区分「回复确实解析成了 JSON」与「只是纯文本/空回复」：能解析成 JSON
294	// 却没有合格 error 或有效数量的回复，不能把整个结构当作说明或成功依据。
295	// 回复体读取失败时返回 null：此时不知道服务是否已经写入，调用方按无法确认处理。
296	async function readServiceReply(res) {
297	  let raw;
298	  try {
299	    raw = await res.text();
300	  } catch (readErr) {
301	    return null;
302	  }
303	  let data = null;
304	  let parsed = false;
305	  if (raw.trim()) {
306	    try {
307	      data = JSON.parse(raw);
308	      parsed = true;
309	    } catch {
310	      data = null;
311	      parsed = false;
312	    }
313	  }
314	  return {raw, data, parsed};
315	}
316	
317	// CSV 导入与批量修改共用的可读原因识别：回复成功解析为 JSON 时，只取对象中的
318	// 非空文本 error；只有回复不是 JSON 结构化数据时，才把纯文本原文（去首尾空白，
319	// 最多前 200 个字符）当作原因。能解析成 JSON 却没有合格 error 的回复
320	// （如 {"message":"..."}、null、[]、字符串形式的 JSON），或 error 只有空白、
321	// 不是文本，都不算可读原因，不向用户倾倒结构；空回复同样返回空串。
322	// trimJsonReason 只控制 JSON error 的呈现方式：导入去掉首尾空白，批量修改保留原文。
323	function serviceReadableError(parsed, data, raw, trimJsonReason) {
324	  if (parsed) {
325	    if (data && typeof data === "object" && !Array.isArray(data) &&
326	        typeof data.error === "string") {
327	      const reason = trimJsonReason ? data.error.trim() : data.error;
328	      if (reason.trim()) return reason;
329	    }
330	    return "";
331	  }
332	  return (raw || "").trim().slice(0, 200);
333	}
334	
335	// 没有取得可靠保存结论时的统一口径（非 400 错误、400 无可读原因、连接中断、
336	// 回复无法读取/解析、成功状态却没有有效处理数量）：不显示成功数量，不断言
337	// 客户资料一定未变或已经回滚，也不按旧表格内容推算本次是否成功；请用户先
338	// 核对客户列表再主动决定是否重新保存。勾选、字段操作与已填内容全部保留，
339	// 不执行保存成功后的清理，也不自动再次发送修改。
340	function unconfirmedBatchHtml(prefix) {
341	  return '<div class="banner bad">' + prefix +
342	    "本次修改是否生效暂时无法确认，客户资料可能已经改变，不能视为全部未修改或已经回滚；" +
343	    "请先核对客户列表，再决定是否重新保存。当前勾选、字段操作与已填内容均已保留，" +
344	    "不会自动重新提交。</div>";
345	}
346	
347	document.getElementById("check-all").addEventListener("change", e => {
348	  if (e.target.checked) clients.forEach(r => selected.add(r.id));
349	  else selected.clear();
350	  renderClients();
351	  renderSelection();
352	});
353	
354	document.getElementById("clients-body").addEventListener("change", e => {
355	  if (!e.target.classList.contains("row-check")) return;
356	  const id = Number(e.target.value);
357	  if (e.target.checked) selected.add(id);
358	  else selected.delete(id);
359	  renderSelection();
360	});
361	
362	document.getElementById("sel-list").addEventListener("click", e => {
363	  const btn = e.target.closest("[data-remove]");
364	  if (!btn) return;
365	  selected.delete(Number(btn.dataset.remove));
366	  renderClients();
367	  renderSelection();
368	});
369	
370	document.getElementById("batch-form").addEventListener("submit", async e => {
371	  e.preventDefault();
372	  // 等待结果期间再次提交（重复点击、回车等）一律忽略：不增加请求、不提前显示成功、
373	  // 不清除已填内容；等待期间的勾选变化也不会在结果返回后自动补交。
374	  if (batchSaving) return;
375	  if (!selected.size) {
376	    showBatchReport('<div class="banner bad">请先勾选至少一名客户。</div>');
377	    syncSubmitState();
378	    return;
379	  }
