728	    raw_ids = payload.get("ids")
729	    if not isinstance(raw_ids, list):
730	        raise BatchUpdateError("ids 必须是客户编号数组")
731	    if not raw_ids:
732	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
733	
734	    ids = []
735	    seen_ids = set()
736	    for raw_id in raw_ids:
737	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
738	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
739	        if raw_id > MAX_CLIENT_ID:
740	            raise BatchUpdateError(
741	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
742	                % (raw_id, MAX_CLIENT_ID))
743	        if raw_id not in seen_ids:
744	            seen_ids.add(raw_id)
745	            ids.append(raw_id)
746	
747	    raw_updates = payload.get("updates", {})
748	    if not isinstance(raw_updates, dict):
749	        raise BatchUpdateError("updates 必须是字段修改说明对象")
750	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
751	    if extra:
752	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
753	
754	    actions = {}
755	    for field_name in OPTIONAL_FIELDS:
756	        spec = raw_updates.get(field_name, {"op": "keep"})
757	        if not isinstance(spec, dict):
758	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
759	        op = spec.get("op")
760	        if op not in ("keep", "set", "clear"):
761	            raise BatchUpdateError(
762	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
763	        if op == "keep":
764	            continue
765	        if op == "clear":
766	            actions[field_name] = None
767	        else:
768	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
769	
770	    if not actions:
771	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
772	
773	    # 一次选择的客户数可能超过 SQLite 单条语句的参数上限，存在性检查与 UPDATE
774	    # 都按参数上限分块；UPDATE 的多个分块在同一事务内一次提交，整笔修改要么
775	    # 全部生效要么全部不生效，不会因分块变成多次部分修改。
776	    variable_limit = sql_variable_limit(database)
777	
778	    existing = set()
779	    for id_chunk in _chunked(ids, variable_limit):
780	        placeholders = ",".join("?" for _ in id_chunk)
781	        existing.update(
782	            row[0]
783	            for row in database.execute(
784	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
785	            )
786	        )
787	    missing = [cid for cid in ids if cid not in existing]
788	    if missing:
789	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
790	
791	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
792	    id_chunk_size = max(1, variable_limit - len(actions))
793	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
794	    values = list(actions.values())
795	    try:
796	        for id_chunk in _chunked(ids, id_chunk_size):
797	            placeholders = ",".join("?" for _ in id_chunk)
798	            database.execute(
799	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
800	                values + id_chunk,
801	            )
802	        database.commit()
803	    except sqlite3.DatabaseError:
804	        database.rollback()
805	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
806	
807	    return {"updated_count": len(ids)}
