810	def parse_csv(text):
811	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
812	
813	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
814	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
815	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
816	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
817	    - 文件结束时仍有字段处于引号内（引号未闭合）。
818	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
819	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
820	    """
821	    rows = []
822	    record = []
823	    field = []
824	    quoted = False        # 当前字段处于引号内
825	    started = False       # 当前字段已经开始（已有内容或已进入引号）
826	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
827	    record_number = 0     # 0 = 表头，1 起为数据记录
828	    i = 0
829	    n = len(text)
830	
831	    def location():
832	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
833	
834	    def structure_error(kind):
835	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
836	
837	    def finish_record():
838	        nonlocal record, field, started, closed
839	        record.append("".join(field))
840	        rows.append(record)
841	        record = []
842	        field = []
843	        started = False
844	        closed = False
845	
846	    while i < n:
847	        c = text[i]
848	        if quoted:
849	            if c == '"':
850	                if i + 1 < n and text[i + 1] == '"':
851	                    field.append('"')
852	                    i += 2
853	                    continue
854	                quoted = False
855	                closed = True
856	                i += 1
857	                continue
858	            if c == "\r":
859	                # 统一字段内换行符为 LF
860	                if i + 1 < n and text[i + 1] == "\n":
861	                    i += 1
862	                field.append("\n")
863	                i += 1
864	                continue
865	            field.append(c)
866	            i += 1
867	            continue
868	        if closed:
869	            # 引号已结束，只允许逗号、记录换行或文件结束
870	            if c == ",":
871	                record.append("".join(field))
872	                field = []
873	                started = False
874	                closed = False
875	            elif c in "\r\n":
876	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
877	                    i += 1
878	                finish_record()
879	                record_number += 1
880	            else:
881	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
882	            i += 1
883	            continue
884	        if c == '"' and not started:
885	            quoted = True
886	            started = True
887	        elif c == '"':
888	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
889	        elif c == ",":
890	            record.append("".join(field))
891	            field = []
892	            started = False
893	        elif c in "\r\n":
894	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
895	                i += 1
896	            if not started and not record and not field:
897	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
898	                i += 1
899	                continue
900	            finish_record()
901	            record_number += 1
902	        else:
903	            field.append(c)
904	            started = True
905	        i += 1
906	    if quoted:
907	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
908	    if started or field or record or closed:
909	        record.append("".join(field))
910	        rows.append(record)
911	    if not rows:
912	        raise FileError("CSV 内容为空：缺少表头")
913	    return rows[0], rows[1:]
