916	def check_date(value):
917	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
918	    match = DATE_RE.match(value)
919	    if not match:
920	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
921	    try:
922	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
923	    except ValueError:
924	        return False, "重要日期无效（%s）：不是真实日历日期" % value
925	    return True, None
