928	def import_clients(database, text):
929	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
930	    header, data_rows = parse_csv(text)
931	    headers = [h.strip() for h in header]
932	
933	    seen = set()
934	    duplicates = []
935	    for h in headers:
936	        if h in seen and h not in duplicates:
937	            duplicates.append(h)
938	        seen.add(h)
939	    if duplicates:
940	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
941	    unknown = [h for h in headers if h not in ALL_COLUMNS]
942	    if unknown:
943	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
944	    if "name" not in headers:
945	        raise FileError("缺少名称列：表头必须包含 name 列")
946	
947	    index = {h: i for i, h in enumerate(headers)}
948	    name_index = index["name"]
949	    date_index = index.get("important_date")
950	
951	    existing = {}
952	    for cid, cname in database.execute("SELECT id, name FROM clients"):
953	        existing[(cname or "").strip().casefold()] = cid
954	
955	    imported = []
956	    failures = []
957	    seen_in_file = {}
958	
959	    for row_number, raw in enumerate(data_rows, start=1):
960	        if len(raw) != len(headers):
961	            failures.append({
962	                "row": row_number,
963	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
964	            })
965	            continue
966	
967	        name = raw[name_index].strip()
968	        problems = []
969	        if not name:
970	            problems.append("缺少名称：name 列为空")
971	        date_value = ""
972	        if date_index is not None:
973	            date_value = raw[date_index].strip()
974	            if date_value:
975	                ok, reason = check_date(date_value)
976	                if not ok:
977	                    problems.append(reason)
978	        if problems:
979	            failures.append({"row": row_number, "reason": "；".join(problems)})
980	            continue
981	
982	        key = name.casefold()
983	        if key in existing:
984	            failures.append({
985	                "row": row_number,
986	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
987	            })
988	            continue
989	        if key in seen_in_file:
990	            failures.append({
991	                "row": row_number,
992	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
993	            })
994	            continue
995	
996	        seen_in_file[key] = row_number
997	        record = {"name": name}
998	        for field_name in OPTIONAL_FIELDS:
999	            idx = index.get(field_name)
1000	            value = raw[idx].strip() if idx is not None else ""
1001	            record[field_name] = value or None
1002	        imported.append((row_number, record))
1003	
1004	    # 全部有效新客户在同一事务内逐条写入并在最后一次提交：只要保存已经开始
1005	    # （已有一条 INSERT 执行），无论后续某条写入失败还是最终提交失败，都回滚
1006	    # 整笔事务——本次文件中的任何新客户都不保留，原有客户资料保持原样，
1007	    # 并以明确的保存失败错误拒绝整次导入，不返回任何新增数量。
1008	    saved = []
1009	    try:
1010	        for row_number, record in imported:
1011	            cursor = database.execute(
1012	                "INSERT INTO clients (name, source, region, industry, important_date)"
1013	                " VALUES (:name, :source, :region, :industry, :important_date)",
1014	                record,
1015	            )
1016	            saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
1017	        database.commit()
1018	    except sqlite3.DatabaseError:
1019	        database.rollback()
1020	        raise ImportSaveError("保存失败：数据库写入出错，本次导入已全部撤销，没有新增任何客户")
1021	
1022	    return {
1023	        "imported_count": len(saved),
1024	        "failed_count": len(failures),
1025	        "imported": saved,
1026	        "failures": failures,
1027	    }
