1030	def main():
1031	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
1032	    commands = parser.add_subparsers(dest="command", required=True)
1033	    serve = commands.add_parser("serve", help="Start the HTTP service")
1034	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
1035	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
1036	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
1037	    args = parser.parse_args()
1038	    if not 0 <= args.port <= 65535:
1039	        parser.error("port must be between 0 and 65535")
1040	    args.data_dir.mkdir(parents=True, exist_ok=True)
1041	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
1042	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
1043	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
1044	    for field_name in OPTIONAL_FIELDS:
1045	        if field_name not in columns:
1046	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
1047	    database.commit()
