1049	    class Handler(BaseHTTPRequestHandler):
1050	        def respond(self, status, value, *, html=False, allow=None):
1051	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
1052	            self.send_response(status)
1053	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
1054	            self.send_header("Content-Length", str(len(payload)))
1055	            if status == 405:
1056	                self.send_header("Allow", allow or "GET")
1057	            self.end_headers()
1058	            self.wfile.write(payload)
1059	
1060	        def handle_import(self):
1061	            try:
1062	                length = int(self.headers.get("Content-Length") or 0)
1063	            except ValueError:
1064	                length = 0
1065	            if length > MAX_BODY:
1066	                self.respond(400, {"error": "文件过大：超过 %d 字节上限" % MAX_BODY})
1067	                return
1068	            raw_body = self.rfile.read(length) if length > 0 else b""
1069	            try:
1070	                text = raw_body.decode("utf-8-sig")
1071	            except UnicodeDecodeError:
1072	                self.respond(400, {"error": "编码错误：文件不是有效的 UTF-8 文本"})
1073	                return
1074	            try:
1075	                result = import_clients(database, text)
1076	            except FileError as exc:
1077	                database.rollback()
1078	                self.respond(400, {"error": str(exc)})
1079	                return
1080	            except ImportSaveError as exc:
1081	                # import_clients 已回滚本次全部新增；这里再确保连接上不留未提交
1082	                # 事务，避免后续请求（列表读取、其他导入、批量修改）顺带提交。
1083	                database.rollback()
1084	                self.respond(400, {"error": str(exc)})
1085	                return
1086	            self.respond(200, result)
1087	
1088	        def handle_batch_update(self):
1089	            try:
1090	                length = int(self.headers.get("Content-Length") or 0)
1091	            except ValueError:
1092	                length = 0
1093	            if length > MAX_BODY:
1094	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
1095	                return
1096	            raw_body = self.rfile.read(length) if length > 0 else b""
1097	            try:
1098	                payload = json.loads(raw_body.decode("utf-8"))
1099	            except (UnicodeDecodeError, json.JSONDecodeError):
1100	                self.respond(400, {"error": "请求体不是有效的 UTF-8 JSON 对象"})
1101	                return
1102	            try:
1103	                result = batch_update_clients(database, payload)
1104	            except BatchUpdateError as exc:
1105	                database.rollback()
1106	                self.respond(400, {"error": str(exc)})
1107	                return
1108	            self.respond(200, result)
1109	
1110	        def route(self):
1111	            location = urlsplit(self.path).path
1112	            if location not in (
1113	                "/", "/health", "/api/clients",
1114	                "/api/clients/import", "/api/clients/batch-update",
1115	            ):
1116	                self.respond(404, {"error": "not found"})
1117	                return
1118	            if location == "/api/clients/import":
1119	                if self.command != "POST":
1120	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
1121	                    return
1122	                self.handle_import()
1123	                return
1124	            if location == "/api/clients/batch-update":
1125	                if self.command != "POST":
1126	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
1127	                    return
1128	                self.handle_batch_update()
1129	                return
1130	            if self.command != "GET":
1131	                self.respond(405, {"error": "method not allowed"}, allow="GET")
1132	                return
1133	            if location == "/":
1134	                self.respond(200, PAGE, html=True)
1135	            elif location == "/health":
1136	                self.respond(200, {"status": "ok", "product": PRODUCT})
1137	            else:
1138	                records = [
1139	                    {
1140	                        "id": row[0],
1141	                        "name": row[1],
1142	                        "source": row[2],
1143	                        "region": row[3],
1144	                        "industry": row[4],
1145	                        "important_date": row[5],
1146	                    }
1147	                    for row in database.execute(
1148	                        "SELECT id, name, source, region, industry, important_date FROM clients ORDER BY id"
1149	                    )
1150	                ]
1151	                self.respond(200, {RESOURCE: records})
1152	
1153	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
1154	
1155	    def stop(_signal, _frame):
1156	        raise KeyboardInterrupt
1157	
1158	    signal.signal(signal.SIGTERM, stop)
1159	    server = None
1160	    try:
1161	        server = HTTPServer((args.host, args.port), Handler)
1162	        host, port = server.server_address[:2]
1163	        address = f"[{host}]" if ":" in host else host
1164	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
1165	        server.serve_forever()
1166	    except KeyboardInterrupt:
