100	  const res = await fetch(base + "/api/clients/import", {method: "POST", body: csv});
101	  const data = await res.json();
102	  if (res.status !== 200) throw new Error("seed 失败：" + JSON.stringify(data));
103	  return data;
104	}
105	
106	// 直接打后端准备稳定的测试数据
107	async function seed(base, rows) {
108	  const lines = rows.map(r => [r.name, r.source ?? "", r.region ?? "", r.industry ?? "", r.date ?? ""]
109	    .map(v => `"${String(v).replace(/"/g, '""')}"`).join(","));
110	  const csv = "name,source,region,industry,important_date\n" + lines.join("\n") + "\n";
111	  const data = await importCsv(base, csv);
112	  return data.imported.map(x => x.id);
113	}
114	
115	async function listClients(base) {
116	  const res = await fetch(base + "/api/clients");
117	  return res.json();
118	}
